# Generated by opscope's homebrew/formula.js from the published release.
# Release: 1.9.0
class Opscope < Formula
  desc "Terminal widgets showing real operational data"
  homepage "https://github.com/stealth-factory/opscope"
  license "AGPL-3.0-or-later"

  depends_on :macos

  on_macos do
    on_arm do
      url "https://github.com/stealth-factory/opscope/releases/download/v1.9.0/opscope-v1.9.0-aarch64-apple-darwin.tar.gz"
      sha256 "98968ac33f6a24000829f817f73fae463766d0d375971a638fde0f00ec7ea537"
    end
    on_intel do
      url "https://github.com/stealth-factory/opscope/releases/download/v1.9.0/opscope-v1.9.0-x86_64-apple-darwin.tar.gz"
      sha256 "e38efe83e753148f650d300067fb6f7db35e256f054a8e34a2e493babe2f7624"
    end
  end

  # Keep every widget beside the launcher, without shadowing tools on PATH.
  BINARY_NAMES = %w[
    agent-usage
    clocks
    github
    github-actions
    github-prs
    herdr-panes
    latency
    linear
    link
    luvus-panes
    matrix
    months
    netwatch
    opscope
    ports
    tailnet
    vercel-deployments
  ].freeze

  def install
    BINARY_NAMES.each { |name| libexec.install name }
    pkgshare.install "docs", "widgets", "README.md", "LICENSE", "config.example.json"
    bin.write_exec_script libexec/"opscope"
  end

  def caveats
    <<~EOS
      Start the menu with opscope, or a widget with opscope clocks.
      Check optional external tools with opscope doctor.
      Settings are saved in ~/.config/opscope/config.json (or OPSCOPE_CONFIG).
      Example configuration and documentation: #{pkgshare}
    EOS
  end

  test do
    assert_equal(["opscope"], bin.children.map { |file| file.basename.to_s })
    assert_match "opscope #{version}", shell_output("#{bin}/opscope --version")
    BINARY_NAMES.each do |name|
      assert_match "#{name} #{version}", shell_output("#{libexec}/#{name} --version")
    end
    assert_match "Clocks:", shell_output("#{bin}/opscope clocks --help")
  end
end
